#!/bin/sh
# Compile zrn-modem-overlay.dts and turn it into zrn_overlay_blob.c, the
# overlay zrn-modem.ko applies when it loads.
cd "$(dirname "$0")"
DTC=${DTC:-../../build/linux-7.1/out/scripts/dtc/dtc}
$DTC -q -I dts -O dtb -o zrn-modem-overlay.dtbo zrn-modem-overlay.dts || exit 1
python3 -I - <<'PY'
data = open('zrn-modem-overlay.dtbo', 'rb').read()
rows = [', '.join('0x%02x' % b for b in data[i:i + 12]) for i in range(0, len(data), 12)]
open('zrn_overlay_blob.c', 'w').write(
    '/* generated by mkoverlay.sh from zrn-modem-overlay.dts: do not edit */\n'
    '#include <linux/types.h>\n'
    'const u8 zrn_overlay[] __aligned(8) = {\n\t' + ',\n\t'.join(rows) + '\n};\n'
    'const u32 zrn_overlay_size = %d;\n' % len(data))
PY
